mapper.select:
SELECT
	member_pass AS memberPass
FROM
	member
WHERE
	member_id = #{mid}
AND member_name = #{name}
AND member_email = #{email}

mapper.update:
UPDATE member
SET image_version = 1
WHERE member_seq = #{memberSeq}

UPDATE MEMBER SET MEMBER_EMAIL = #{memberEmail}, MEMBER_PHONE = #{memberPhone},
MEMBER_PASS = #{memberPass},
CREATE_DT = NOW() WHERE MEMBER_ID = #{memberId}

UPDATE member
SET image_version = image_version + 1
WHERE member_seq = #{memberSeq}
